// Cross-reference leads we followed vs who actually followed us back
// Input 0: follower set from Build Follower Set
// Leads: pulled from Get Followed Leads via node reference

const followerSetItem = $input.first();
const followerSet = new Set((followerSetItem.json.followerSet || []).map(u => u.toLowerCase()));

console.log('Follower set size for matching: ' + followerSet.size);

// Grab the leads that passed the 24h gate
const leads = $('24h Gate and Not Yet Matched').all();

const newFollowBacks = leads.filter(lead => {
  const username = (lead.json.username || '').toLowerCase().trim();
  return username && followerSet.has(username);
}).map(lead => ({
  json: {
    username: lead.json.username,
    platform: lead.json.platform,
    followedBack: 'true',
    followedBackAt: new Date().toISOString()
  }
}));

console.log('New follow-backs found: ' + newFollowBacks.length);

if (newFollowBacks.length === 0) {
  return [{ json: { _skip: true } }];
}

return newFollowBacks;

// Build a unified Set of all followers from IG + X API responses
// IG response shape: { data: [ { username: '...' }, ... ] }
// X response shape:  { data: [ { username: '...' }, ... ] }

const ourFollowers = new Set();

for (const item of $input.all()) {
  const raw = item.json;

  // Handle IG follower list (data array)
  const igData = raw.data;
  if (Array.isArray(igData)) {
    for (const f of igData) {
      const u = (f.username || f.userName || '').toLowerCase().trim();
      if (u) ourFollowers.add(u);
    }
  }

  // Handle X follower list (also data array but nested differently)
  // X returns { data: [ { id, name, username }, ... ] }
  if (raw.data && Array.isArray(raw.data)) {
    for (const f of raw.data) {
      const u = (f.username || '').toLowerCase().trim();
      if (u) ourFollowers.add(u);
    }
  }

  // Flat username field fallback (for simulation / manual test)
  const u = (raw.username || raw.ownerUsername || '').toLowerCase().trim();
  if (u) ourFollowers.add(u);
}

console.log('Total real followers loaded: ' + ourFollowers.size);

// Pass the followers set as a single item for the match step
return [{ json: { followerSet: Array.from(ourFollowers) } }];

// Build a set of all usernames currently following us (from IG + X scrape)
const followerItems = $('Merge Follower Lists1').all();
const ourFollowers = new Set();

for (const f of followerItems) {
  const d = f.json;
  // IG profile scraper returns followers in d.followers array
  const followersArr = d.followers || d.latestFollowers || [];
  for (const u of followersArr) {
    const name = (u.username || u.userName || u.screen_name || '').toLowerCase();
    if (name) ourFollowers.add(name);
  }
  // X user scraper may return flat user objects
  const uFlat = (d.userName || d.username || d.screen_name || '').toLowerCase();
  if (uFlat) ourFollowers.add(uFlat);
}

console.log('Total followers indexed:', ourFollowers.size);

// Filter leads that now appear in our followers
const leads = $('Filter Not Yet Followed Back').all();
const matches = leads.filter(lead => {
  return ourFollowers.has((lead.json.username || '').toLowerCase());
});

console.log('New follow-backs detected:', matches.length);

if (matches.length === 0) return [];

return matches.map(lead => ({
  json: {
    username: lead.json.username,
    platform: lead.json.platform
  }
}));

const GEO = ['us','usa','united states','uk','london','canada','australia',
  'new york','san francisco','toronto','mumbai','bangalore','dubai','singapore'];
const T1 = ['ai','automation','agency','saas'];
const T2 = ['marketing','growth','startup','consultant','founder','ceo',
  'chatgpt','gpt','openai','n8n','zapier'];
const T3 = ['digital','freelance','business','entrepreneur','coach'];

const results = [];

for (const item of $input.all()) {
  const d = item.json;

  // User-scraper returns flat profile fields directly
  const username = d.userName || d.username || d.screen_name || '';
  if (!username || username === 'undefined') continue;

  const bio = (d.description || d.bio || '').toLowerCase();
  const fc = d.followers || d.followersCount || d.followers_count || 0;
  const loc = (d.location || bio).toLowerCase();

  let fs = 0;
  if (fc >= 200 && fc < 1000) fs = 10;
  else if (fc >= 1000 && fc < 5000) fs = 22;
  else if (fc >= 5000 && fc < 20000) fs = 30;
  else if (fc >= 20000 && fc < 50000) fs = 25;
  else if (fc >= 50000 && fc <= 100000) fs = 15;

  const bs = Math.min(
    T1.filter(k => bio.includes(k)).length * 10 +
    T2.filter(k => bio.includes(k)).length * 5 +
    T3.filter(k => bio.includes(k)).length * 3,
    40
  );

  const geo = GEO.some(g => loc.includes(g));
  const score = Math.min(fs + bs + (geo ? 5 : 0), 100);

  results.push({
    json: {
      platform: 'twitter',
      username,
      displayName: d.name || d.displayName || '',
      bio: d.description || d.bio || '',
      followerCount: fc,
      engagementRate: 0,
      leadScore: score,
      profileUrl: 'https://twitter.com/' + username,
      postCaption: '',
      location: d.location || '',
      scrapedAt: new Date().toISOString(),
      geoMatch: geo ? 'yes' : 'no',
      status: 'new'
    }
  });
}

console.log('Valid X leads:', results.length);
return results;

