const GEO = ['us','usa','united states','uk','london','canada','australia','india','new york','san francisco','los angeles','toronto','mumbai','bangalore','dubai','singapore','berlin','amsterdam'];
const T1 = ['ai','automation','agency','saas'];
const T2 = ['marketing','growth','tech','startup','consultant','founder','ceo','chatgpt','gpt','openai','n8n','zapier'];
const T3 = ['digital','freelance','business','entrepreneur','coach','strategist'];

return $input.all().map(item => {
  const d = item.json;
  const fc = d.followersCount || 0;
  const er = fc > 0 ? ((d.likesCount || 0) + (d.commentsCount || 0)) / fc : 0;
  const bio = (d.biography || '').toLowerCase();
  const loc = (d.location || bio).toLowerCase();

  // Follower bell-curve scoring (max 30)
  let fs = 0;
  if (fc >= 500 && fc < 1000) fs = 10;
  else if (fc >= 1000 && fc < 5000) fs = 22;
  else if (fc >= 5000 && fc < 20000) fs = 30;
  else if (fc >= 20000 && fc < 50000) fs = 25;
  else if (fc >= 50000 && fc <= 100000) fs = 15;

  // Engagement score (max 30)
  const es = Math.min(Math.round(er * 1000), 30);

  // Bio keyword score (max 40)
  const bs = Math.min(
    T1.filter(k => bio.includes(k)).length * 10 +
    T2.filter(k => bio.includes(k)).length * 5 +
    T3.filter(k => bio.includes(k)).length * 3,
    40
  );

  const geo = GEO.some(g => loc.includes(g));
  const score = Math.min(fs + es + bs + (geo ? 5 : 0), 100);

  return {
    json: {
      platform: 'instagram',
      username: d.username || '',
      displayName: d.fullName || '',
      bio: d.biography || '',
      followerCount: fc,
      engagementRate: parseFloat(er.toFixed(4)),
      leadScore: score,
      profileUrl: 'https://instagram.com/' + (d.username || ''),
      postCaption: d.postCaption || '',
      location: d.location || '',
      scrapedAt: new Date().toISOString(),
      geoMatch: geo ? 'yes' : 'no',
      status: 'new'
    }
  };
}).filter(i => i.json.username && i.json.followerCount <= 100000);

// Merge post-level data (captions, likes) with profile-level data (bio, followers)
// Input 0 = extracted post data (username + postCaption + likes)
// Input 1 = enriched profile data (biography + followersCount)
const postItems = $input.all(); // comes as flat list from last node

// We need to get profile data — use $('Enrich IG Profiles1').all()
let profiles = [];
try {
  profiles = $('Enrich IG Profiles1').all();
} catch(e) {
  profiles = [];
}

// Build profile lookup map
const profileMap = {};
for (const p of profiles) {
  const d = p.json;
  const u = d.username || d.userName || '';
  if (u) profileMap[u.toLowerCase()] = d;
}

// Merge post data with profile data
const result = [];
for (const item of $('Extract IG Usernames1').all()) {
  const post = item.json;
  const key = (post.username || '').toLowerCase();
  const profile = profileMap[key] || {};

  result.push({
    json: {
      username: post.username,
      postCaption: post.postCaption,
      location: post.location || profile.city || profile.businessAddress?.city || '',
      likesCount: post.likesCount,
      commentsCount: post.commentsCount,
      // Profile fields — now properly sourced
      biography: profile.biography || profile.bio || '',
      followersCount: profile.followersCount || profile.followers || 0,
      fullName: profile.fullName || profile.name || '',
      externalUrl: profile.externalUrl || ''
    }
  });
}

return result;

const seen = new Set();
const usernames = [];

// Pre-filter keywords — only enrich if post caption signals relevance
const SIGNAL_WORDS = ['ai','automation','agency','saas','founder','ceo',
  'consultant','marketing','chatgpt','n8n','zapier','startup','growth'];

for (const item of $input.all()) {
  const d = item.json;
  const posts = Array.isArray(d) ? d : [d];
  for (const post of posts) {
    const u = post.ownerUsername || post.username || '';
    if (!u || seen.has(u)) continue;

    const caption = (post.caption || '').toLowerCase();
    const hasSignal = SIGNAL_WORDS.some(k => caption.includes(k));

    // Only add to enrichment queue if caption has a signal word
    if (hasSignal) {
      seen.add(u);
      usernames.push({
        json: {
          username: u,
          postCaption: (post.caption || '').substring(0, 200),
          location: post.locationName || '',
          likesCount: post.likesCount || 0,
          commentsCount: post.commentsCount || 0
        }
      });
    }
  }
}

console.log(`Caption pre-filter: ${usernames.length} of ${seen.size + usernames.length} accounts queued for enrichment`);
return usernames.length > 0 ? usernames : [];


