// ─────────────────────────────────────────────────────────────
// SIMULATION MODE
// In production, replace this node with two HTTP Request nodes:
//   - Unfollow check: call IG/X API to get our current following list
//     → if a lead we followed is no longer in that list = UNFOLLOW
//   - Block check: call IG/X API to verify we can still see their profile
//     → if profile returns 404 or restricted = BLOCK
//
// For now: randomly simulate ~15% unfollow and ~5% block rate
// Only checks leads where followedBack = true (active relationships)
// ─────────────────────────────────────────────────────────────

const leads = $input.all();
const events = [];

console.log('Checking', leads.length, 'active leads for unfollow/block events');

for (const item of leads) {
  const d = item.json;
  const username = (d.username || '').trim();
  if (!username) continue;

  // Skip if already flagged as unfollowed or blocked
  const currentStatus = (d.status || '').toLowerCase();
  if (currentStatus === 'unfollowed' || currentStatus === 'blocked') continue;

  const rand = Math.random();

  if (rand < 0.05) {
    // 5% chance — BLOCK detected
    console.log('[SIM] BLOCK detected: @' + username);
    events.push({
      json: {
        username,
        platform: d.platform || '',
        eventType: 'block',
        eventDetail: 'Profile returned restricted/404 — user likely blocked us',
        previousStatus: d.status || '',
        status: 'blocked',
        detectedAt: new Date().toISOString()
      }
    });
  } else if (rand < 0.20) {
    // 15% chance — UNFOLLOW detected
    console.log('[SIM] UNFOLLOW detected: @' + username);
    events.push({
      json: {
        username,
        platform: d.platform || '',
        eventType: 'unfollow',
        eventDetail: 'User no longer appears in our followers list',
        previousStatus: d.status || '',
        status: 'unfollowed',
        detectedAt: new Date().toISOString()
      }
    });
  }
}

console.log('Events found — Unfollows + Blocks:', events.length);
if (events.length === 0) return [{ json: { _skip: true } }];
return events;

const items = $input.all();
const today = items[0]?.json?._today || $now.toFormat('yyyy-LL-dd');
const totalFollowBacks = Number(items[0]?.json?._allFollowBacks || 0);

const ig = items.filter(i => (i.json.platform || '').toLowerCase() === 'instagram');
const x  = items.filter(i => (i.json.platform || '').toLowerCase() === 'twitter');

const igFollows = ig.filter(i => i.json.followedAt).length;
const xFollows  = x.filter(i => i.json.followedAt).length;
const totalFollows = igFollows + xFollows;

const followBackRate = totalFollows > 0
  ? ((totalFollowBacks / totalFollows) * 100).toFixed(1) + '%'
  : '0.0%';

const igDMs = ig.filter(i => String(i.json.dmSent).toLowerCase() === 'true').length;
const xDMs  = x.filter(i => String(i.json.dmSent).toLowerCase() === 'true').length;
const totalDMs = igDMs + xDMs;

const totalReplies = items.filter(i => i.json.repliedAt).length;

const conversionRate = totalDMs > 0
  ? ((totalReplies / totalDMs) * 100).toFixed(1) + '%'
  : '0.0%';

const totalFollowUps = items.filter(i => parseInt(i.json.followUpStep || 0) >= 1).length;

const scores = items.map(i => parseFloat(i.json.leadScore) || 0);
const avgLeadScore = scores.length > 0
  ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(1)
  : '0.0';

return [{ json: {
  reportDate:      today,
  totalLeadsToday: items.length,
  igLeadsToday:    ig.length,
  xLeadsToday:     x.length,
  igFollows,
  xFollows,
  totalFollows,
  totalFollowBacks,
  followBackRate,
  igDMsSent:       igDMs,
  xDMsSent:        xDMs,
  totalDMsSent:    totalDMs,
  totalReplies,
  conversionRate,
  totalFollowUps,
  avgLeadScore
} }];

// Capture a lightweight snapshot of ALL leads BEFORE the filter.
// Tags each row with _today (Luxon-safe) and _allFollowBacks so the
// Compute node never needs a cross-node $() reference.
const allItems = $input.all();
const today = $now.toFormat('yyyy-LL-dd'); // LL = month in Luxon (MM = minutes!)
const allFollowBacks = allItems.filter(i => String(i.json.followedBack).toLowerCase() === 'true').length;

return allItems.map(item => ({
  json: {
    ...item.json,
    _today: today,
    _allFollowBacks: allFollowBacks
  }
}));
